<!doctype html>
<html lang="fa" dir="rtl">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
  <title>ویترین‌یاب | جستجوی هوشمند پوشاک</title>
  <link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root{--ink:#182217;--green:#236447;--lime:#d8ef7c;--cream:#f8f8f1;--muted:#687168;--line:#e3e6dd}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font-family:Vazirmatn,system-ui,sans-serif}.container{max-width:1180px;margin:auto;padding:0 22px}.top{height:76px;display:flex;justify-content:space-between;align-items:center}.logo{font-size:22px;font-weight:800}.logo i{display:inline-grid;place-items:center;width:31px;height:31px;color:#fff;background:var(--green);border-radius:10px;font-style:normal;margin-left:8px}.nav{display:flex;gap:24px;color:#526051;font-size:14px}.login{border:1px solid var(--line);border-radius:12px;padding:10px 15px;background:#fff;font-family:inherit;cursor:pointer}.hero{text-align:center;padding:68px 0 31px;background:radial-gradient(circle at 50% 0,#e8f6b7 0,transparent 44%)}h1{font-size:clamp(29px,5vw,53px);margin:0;font-weight:800;letter-spacing:-2px}.hero p{color:var(--muted);margin:16px auto 28px;max-width:590px;line-height:2}.searchbox{max-width:830px;margin:auto;background:#fff;border:1px solid #dce4d5;border-radius:21px;padding:9px;box-shadow:0 17px 32px #394e2314;display:flex;gap:8px;align-items:center}.searchbox input{border:0;outline:0;flex:1;min-width:0;padding:13px;font:inherit}.iconbtn,.submit{border:0;border-radius:14px;height:49px;display:grid;place-items:center;cursor:pointer;font-family:inherit}.iconbtn{width:49px;background:#f0f4e9;color:var(--green);font-size:21px}.submit{background:var(--green);color:white;padding:0 22px;font-weight:700}.hint{margin-top:13px;color:#879081;font-size:12px}.hint span{background:#edf2e7;color:#4d684e;border-radius:100px;padding:3px 9px;margin:0 2px}.stats{display:flex;justify-content:center;gap:45px;margin:32px 0 12px}.stat b{display:block;font-size:18px}.stat{font-size:12px;color:var(--muted)}.section-head{display:flex;align-items:end;justify-content:space-between;margin:34px 0 17px}.section-head h2{margin:0;font-size:21px}.section-head a{font-size:13px;color:var(--green);text-decoration:none}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:17px;padding-bottom:60px}.card{background:#fff;border:1px solid var(--line);border-radius:18px;overflow:hidden;cursor:pointer;transition:.2s}.card:hover{transform:translateY(-4px);box-shadow:0 13px 25px #22331917}.photo{height:250px;position:relative;background-size:cover;background-position:center}.photo:after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,transparent 55%,#101a0d80)}.match{position:absolute;z-index:1;top:12px;right:12px;background:var(--lime);padding:6px 9px;border-radius:9px;font-weight:800;font-size:12px}.cardbody{padding:13px 14px 15px}.product{font-size:14px;font-weight:700;margin:0 0 7px}.place{font-size:12px;color:var(--muted);margin:0}.pin{color:var(--green);font-size:14px}.empty{grid-column:1/-1;background:#fff;border:1px dashed #cbd5c3;border-radius:18px;padding:37px;text-align:center;color:var(--muted)}.dialog{position:fixed;inset:0;background:#12201488;display:none;align-items:end;justify-content:center;z-index:4}.dialog.open{display:flex}.drawer{background:white;border-radius:25px 25px 0 0;width:min(680px,100%);padding:24px;animation:rise .25s}.drawer h3{margin:0 0 8px}.drawer p{color:var(--muted);font-size:14px}.map{height:195px;border-radius:16px;background:linear-gradient(135deg,#dae9c5,#f3e8c9);position:relative;overflow:hidden;margin:18px 0}.map:before,.map:after{content:'';position:absolute;background:#fff9;border-radius:99px;transform:rotate(-25deg)}.map:before{width:140%;height:22px;top:73px;right:-60px}.map:after{height:150%;width:22px;right:48%;top:-30px}.marker{position:absolute;z-index:1;top:83px;right:48%;background:#e8573c;width:22px;height:22px;border-radius:50% 50% 50% 0;transform:rotate(-45deg);box-shadow:0 3px 6px #0004}.route{display:block;text-align:center;border-radius:13px;padding:13px;background:var(--green);color:#fff;text-decoration:none;font-weight:700}.close{float:left;border:0;background:#eff3ed;border-radius:9px;width:32px;height:32px;cursor:pointer;font-size:17px}@keyframes rise{from{transform:translateY(50px);opacity:0}to{transform:none;opacity:1}}@media(max-width:760px){.top{height:65px}.nav{display:none}.hero{padding-top:39px}.searchbox{flex-wrap:wrap}.searchbox input{order:-1;width:calc(100% - 5px);flex-basis:100%;padding:8px 10px}.iconbtn{flex:1}.submit{flex:2}.stats{gap:24px}.grid{grid-template-columns:repeat(2,1fr);gap:11px}.photo{height:185px}.cardbody{padding:10px}.section-head{margin-top:25px}.product{font-size:12px}.place{font-size:10px}} 
  </style>
</head>
<body>
<header class="container top"><div class="logo"><i>و</i>ویترین‌یاب</div><nav><a>چطور کار می‌کند؟</a><a>فروشگاه‌ها</a><a>درباره ما</a></nav><button class="login">ورود / ثبت‌نام</button></header>
<main>
 <section class="hero"><div class="container"><h1>لباس دلخواهت را، نزدیک خودت پیدا کن</h1><p>با نوشتن توضیح یا آپلود عکس، مشابه‌ترین پوشاک ویترین فروشگاه‌ها را ببین و مستقیم به همان‌جا برو.</p>
 @if ($errors->any())<p style="color:#bd3d31">{{ $errors->first() }}</p>@endif
 <form class="searchbox" method="POST" action="{{ route('search') }}" enctype="multipart/form-data">@csrf
  <button type="button" class="iconbtn" title="گرفتن عکس با دوربین" onclick="document.getElementById('camera').click()">⌾</button>
  <label class="iconbtn" title="بارگذاری تصویر" for="image">⌑</label><input hidden id="image" name="image" type="file" accept="image/*"><input hidden id="camera" name="image" type="file" accept="image/*" capture="environment">
  <input name="text" value="{{ request('text') }}" placeholder="مثلاً: پیراهن مجلسی قرمز پولک‌دار" aria-label="متن جستجو">
  <button class="submit" type="submit">جستجو <span style="font-size:19px;margin-right:7px">←</span></button>
 </form><div class="hint">پیشنهاد: <span>مانتو کتی کرم</span><span>کت جین آبی</span><span>پیراهن مشکی</span></div>
 <div class="stats"><div class="stat"><b>+۱۲٬۰۰۰</b> لباس ثبت‌شده</div><div class="stat"><b>+۸۵۰</b> فروشگاه همکار</div><div class="stat"><b>۳ جستجو</b> هدیه شروع</div></div></div></section>
 <section class="container"><div class="section-head"><div><h2>{{ isset($products) ? 'نتایج مشابه شما' : 'محبوب‌ترین ویترین‌ها' }}</h2><small style="color:var(--muted)">{{ isset($products) ? $products->count().' نتیجه پیدا شد' : 'از فروشگاه‌های اطراف شما' }}</small></div><a href="#">مشاهده همه ←</a></div>
 <div class="grid">
 @forelse(($products ?? collect()) as $product)
 <article class="card" onclick="openDrawer('{{ e($product->name) }}','{{ e($product->shop->name) }}','{{ e($product->shop->address) }}')"><div class="photo" style="background-image:url('{{ asset('storage/'.$product->image_path) }}')"><span class="match">{{ round(($scores[$product->id] ?? 0)*100) }}٪ تطابق</span></div><div class="cardbody"><p class="product">{{ $product->name }}</p><p class="place"><span class="pin">●</span> {{ $product->shop->name }} · {{ $product->shop->mall_name ?? 'فروشگاه مستقل' }}</p></div></article>
 @empty
 @foreach([['مانتو کتی مینیمال','#ddd1bd'],['پیراهن ساتن سبز','#c9d9c6'],['کت جین کلاسیک','#b9c8d2'],['شومیز مجلسی','#ead2c9']] as [$name,$color])
 <article class="card" onclick="openDrawer('{{ $name }}','گالری پوشاک آفتاب','تهران، مرکز خرید پالادیوم، طبقه دوم')"><div class="photo" style="background:linear-gradient(145deg,{{ $color }},#f7f4e9)"><span class="match">۹{{ 1+$loop->index }}٪ تطابق</span></div><div class="cardbody"><p class="product">{{ $name }}</p><p class="place"><span class="pin">●</span> گالری آفتاب · پالادیوم</p></div></article>
 @endforeach
 @endforelse
 </div></section>
</main>
<div class="dialog" id="dialog" onclick="if(event.target===this)closeDrawer()"><div class="drawer"><button class="close" onclick="closeDrawer()">×</button><h3 id="dname">مانتو کتی مینیمال</h3><p id="dshop">گالری پوشاک آفتاب</p><div class="map"><span class="marker"></span></div><p id="daddress">تهران، مرکز خرید پالادیوم، طبقه دوم</p><a id="route" class="route" target="_blank" href="https://www.openstreetmap.org">مسیریابی به فروشگاه</a></div></div>
<script>function openDrawer(n,s,a){dname.textContent=n;dshop.textContent=s;daddress.textContent=a;dialog.classList.add('open')}function closeDrawer(){dialog.classList.remove('open')}</script>
</body></html>
